const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,s,size=17)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${esc(s)}</text>`;
const dot=(x,y,r=9,c='#edab94')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f8e5cd" stroke-width="1"/>`;
const line=(a,b,c='#acc5c7',width=3)=>`<path d="M${a[0]} ${a[1]}L${b[0]} ${b[1]}" fill="none" stroke="${c}" stroke-width="${width}"/>`;
const frame=(art,label)=>`<svg viewBox="0 0 560 360" role="img" aria-label="${esc(label)}"><defs><radialGradient id="filmBall"><stop stop-color="#fce4c2"/><stop offset="1" stop-color="#bc846f"/></radialGradient></defs>${art}</svg>`;
const ball=(x,y,r=18)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="url(#filmBall)"/>`;
export const clampFilm=v=>Math.max(0,Math.min(1,Number(v)||0));
export function filmPhase(time,count){return Math.min(count-1,Math.floor(clampFilm(time)*count));}
const make=(title,steps,note,render)=>({title,steps,note,render,duration:12});
function route(points,names,p,colours=[],closed=true){let art='';for(let i=0;i<points.length;i++){let a=points[i],b=points[(i+1)%points.length];if(closed||i<points.length-1)art+=line([a[0],a[1]+12],[b[0],b[1]+12]);art+=`<rect x="${a[0]-56}" y="${a[1]-24}" width="112" height="48" rx="15" fill="#32516a" stroke="#aac4c6"/>`+text(a[0],a[1]-5,names[i],14);}let segments=closed?points.length:points.length-1,s=p*segments,i=Math.min(segments-1,Math.floor(s)),u=s-i,a=points[i],b=points[(i+1)%points.length];art+=dot(a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u+12,8,colours[i]||'#edab94');return art;}
function transport(p,osmosis=false){let art='<rect x="25" y="60" width="510" height="240" rx="24" fill="#ffffff08" stroke="#abc4c6"/><path d="M280 60V300" stroke="#cbdad7" stroke-width="6" stroke-dasharray="15 7"/>';for(let i=0;i<24;i++){let rightStart=i>=18,x0=rightStart?320+(i%6)*32:60+(i%6)*27,y0=100+Math.floor(i%18/6)*65,sign=i%2?1:-1,x=x0+Math.sin(p*9+i)*12,y=y0+Math.sin(p*12+i*2)*10;if(i<8)x=x0+(360-x0)*p+Math.sin(p*12+i)*8;else if(i>=18&&i<20)x=x0+(180-x0)*p;art+=dot(x,y,7,osmosis?'#b8d6dc':'#edab94');}if(osmosis)for(let i=0;i<8;i++)art+=`<rect x="${335+i%4*42}" y="${135+Math.floor(i/4)*65}" width="18" height="18" rx="3" fill="#dfac85"/>`;return art+text(145,35,osmosis?'More dilute solution':'Higher concentration',17)+text(415,35,osmosis?'More concentrated solution':'Lower concentration',17)+text(280,335,osmosis?'Only water crosses this membrane':'Movement both ways; net transfer down gradient',17);}
export const films={...spa1Films,...mag1Films,...wav1Films,...frc1Films,...rad1Films,...mat2Films,...mat1Films,...el3Films,...el2Films,...el1Films,...phy2Films,...eco2Films,...eco3Films,...eco4Films,...eco5Films,...eco6Films,...phy1Films,...boundFilms,...histFilms,...evoFilms,...familyFilms,...genFilms,...inheritFilms,...growthFilms,...reproFilms,...renalFilms,...endoFilms,...sensesFilms,...neuralFilms,...respFilms,
 diffusion:make('Diffusion: random motion, net spread',['Particles move randomly in both directions.','More leave the higher-concentration region.','Net transfer reduces the concentration difference.','Random motion continues; equilibrium is dynamic.'],'Illustrative particle tracks, not measured paths or rates. Final distribution approaches balance; replay resets the starting gradient.',p=>frame(transport(p),'Particles cross in both directions; net movement from higher to lower concentration.')),
 osmosis:make('Osmosis: follow the water',['Two solutions are separated by a partially permeable membrane.','Water crosses in both directions; these solute particles cannot cross.','Net water transfer is from the more dilute side.','The more concentrated side gains water overall.'],'Fixed reservoirs and enlarged particles simplify changing volumes; water movement continues both ways. Replay resets the gradient.',p=>frame(transport(p,true),'Water crosses the membrane; larger solute squares remain on the concentrated side.')),
 active:make('Active transport: against the gradient',['A substance is at lower concentration outside the cell.','A membrane carrier binds the substance.','Energy from respiration enables transport against the gradient.','The substance is released on the higher-concentration side.'],'One schematic carrier cycle; not a molecular protein structure or measured rate.',p=>{let phase=filmPhase(p,4),x=90+380*p;return frame('<path d="M280 60V300" stroke="#a8c5c9" stroke-width="18"/><rect x="249" y="140" width="62" height="80" rx="22" fill="#d7af8b"/>'+[0,1,2,3,4,5].map(i=>dot(360+i%3*50,110+Math.floor(i/3)*120,7,'#c5dad7')).join('')+ball(x,180,13)+text(135,40,'Lower concentration')+text(415,40,'Higher concentration')+text(280,330,phase===2?'Energy input from respiration':'Membrane carrier cycle'),films.active.steps[phase]);}),
 heart:make('Follow one route through the double circulation',['Body → right atrium.','Right atrium → right ventricle.','Right ventricle → lungs.','Lungs → left atrium.','Left atrium → left ventricle.','Left ventricle → body.'],'A route tracer, not a heartbeat simulation. All routes operate continuously. Oxygenation colours are symbolic; blood is never blue. Chambers are rearranged for route clarity.',p=>frame(route([[280,310],[105,255],[105,125],[280,65],[455,125],[455,255]],['Body','Right atrium','Right ventricle','Lungs','Left atrium','Left ventricle'],p,['#a5c3ce','#a5c3ce','#a5c3ce','#edab94','#edab94','#edab94']),'Tracer follows body, right heart, lungs, left heart, body.')),
 enzyme:make('An enzyme cycle',['A substrate approaches a complementary active site.','The substrate binds to the active site.','The enzyme catalyses the reaction.','Products leave; the enzyme is available again.'],'Schematic breakdown reaction. Shapes and timing are symbolic; the enzyme is not used up. This is not a mechanism for every enzyme reaction.',p=>{let stage=filmPhase(p,4),x=stage<2?90+Math.min(1,p*4)*180:270+(p-.5)*300;let a='<path d="M200 165Q165 70 280 85Q395 70 360 165L305 145V190H255V145Z" fill="#91b4ae" stroke="#d2d9cb" stroke-width="3"/>'+text(280,240,'Enzyme · unchanged');a+=stage<2?`<rect x="${x-22}" y="150" width="44" height="38" rx="4" fill="#edab94"/>`:ball(x,155,13)+ball(x+10+(p-.5)*70,190,13);return frame(a,films.enzyme.steps[stage]);}),
 transpiration:make('Water: soil to atmosphere',['Water enters root hair cells by osmosis.','Water moves into the xylem.','The transpiration stream carries water towards leaves.','Water evaporates from leaf cells and diffuses out through stomata.'],'One highlighted route through continuous transport. Enlarged marker is water, not a single visible droplet; geometry and timing symbolic.',p=>frame(route([[70,275],[190,275],[280,200],[340,90],[475,90]],['Soil','Root hair','Xylem','Leaf cells','Air via stomata'],p,[],false),'Water route from soil through roots and xylem to leaf and air.')),
 phloem:make('Translocation: source to sink',['A source leaf supplies dissolved sugars.','Sugars enter the phloem transport system.','Phloem carries dissolved sugars to a sink.','A sink uses or stores the sugars.'],'Example leaf-to-root route, not the only direction. Other phloem tubes carry sugars towards growing shoots or fruits. The closing reset is not return flow.',p=>{let nodes=[[110,90],[280,90],[280,265],[450,265]],art='';for(let i=0;i<3;i++)art+=line(nodes[i],nodes[i+1]);art+=nodes.map((a,i)=>`<rect x="${a[0]-60}" y="${a[1]-22}" width="120" height="44" rx="14" fill="#32516a"/>`+text(a[0],a[1]+5,['Source leaf','Phloem entry','Phloem tube','Root sink'][i],14)).join('');let s=p*3,i=Math.min(2,Math.floor(s)),u=s-i;return frame(art+dot(nodes[i][0]+(nodes[i+1][0]-nodes[i][0])*u,nodes[i][1]+(nodes[i+1][1]-nodes[i][1])*u),'Dissolved sugar moves from source leaf to a root sink.');}),
 mitosis:make('Cell cycle: copy, separate, divide',['The cell grows and increases subcellular structures.','DNA replicates: each chromosome has two copies.','Chromosome copies separate into two nuclei.','The cytoplasm and cell membrane divide.','Two genetically identical daughter cells result.'],'Five replayable snapshots, not equal-duration phases. Four chromosomes are illustrative, not a universal chromosome count.',p=>cycleFigure({stage:filmPhase(p,5)})),
 resistance:make('Resistance: selection over generations',['The starting population includes resistant variants.','Antibiotic exposure kills susceptible bacteria preferentially.','Resistant survivors remain; the antibiotic did not create their need-directed mutation.','Survivors reproduce and pass on resistance.'],'Supplied cohort counts, not a treatment forecast. Stepwise snapshots compress death and reproduction; no clinical timing implied.',p=>cohortFigure({antibiotic:true,step:[0,1,1,2][filmPhase(p,4)]})),
 monoclonal:make('Making monoclonal antibodies',['Start with a lymphocyte and a tumour cell.','Stimulate the lymphocyte to make a specific antibody.','Fuse the cells: a hybridoma combines antibody production and division.','Select the hybridoma producing the desired antibody.','Clone selected cells and grow them.','Collect and purify the antibodies.'],'Six stepwise snapshots; lab stages are not equal-duration. Selection/purification still require the existing investigation decisions.',p=>specialFigure({kind:'fusion',step:filmPhase(p,6)})),
 photosynthesis:make('Photosynthesis: matter and energy',['Light transfers energy into chloroplasts.','Carbon dioxide and water supply the material reactants.','Endothermic photosynthesis makes glucose.','Oxygen is also produced; atoms are conserved.'],'Overall process summary, not biochemical steps. Stage ordering is explanatory, not reaction kinetics. Glucose and oxygen are products, not light particles.',p=>{let s=filmPhase(p,4),a='<ellipse cx="280" cy="185" rx="105" ry="65" fill="#8aaa96" stroke="#c5d7c6" stroke-width="3"/>'+text(280,191,'Chloroplast');if(s===0)for(let i=0;i<5;i++)a+=line([150+i*50,45],[200+i*30,135],'#edd1a0',3);if(s===1)a+=dot(50+170*(p*4-1),155,14)+text(100,120,'CO₂ + H₂O',18);if(s>=2)a+=dot(390+(p-.5)*180,155,16)+text(450,120,'Glucose',18);if(s===3)a+=dot(390+(p-.75)*260,230,10,'#adcdd1')+text(450,275,'O₂',19);a+=text(280,330,'CO₂ + water → glucose + oxygen',18);return frame(a,films.photosynthesis.steps[s]);}),
 particles:make('Particle motion in three states',['Solid: particles vibrate about fixed positions.','Liquid: particles remain close but move past one another.','Gas: particles are far apart and move freely.'],'Three separate state examples; transition cuts are not a heating curve. Symbolic size, speed and density; particles themselves do not expand.',p=>{let s=filmPhase(p,3),a='<rect x="35" y="60" width="490" height="235" rx="22" fill="#ffffff08" stroke="#b5cdce"/>';for(let i=0;i<20;i++){let x,y;if(s===0){x=180+i%5*45+Math.sin(p*90+i)*3;y=115+Math.floor(i/5)*40+Math.cos(p*90+i)*3;}else if(s===1){x=150+i%5*55+Math.sin(p*15+i)*12;y=110+Math.floor(i/5)*43+Math.cos(p*19+i)*10;}else{x=50+Math.abs(Math.sin(p*5+i*2.4))*450;y=80+Math.abs(Math.sin(p*7+i*1.3))*190;}a+=ball(x,y,10);}return frame(a+text(280,335,['Solid','Liquid','Gas'][s],22),films.particles.steps[s]);}),
 collision:make('One successful collision',['Reactant particles approach.','Particles collide with sufficient energy.','Bonds rearrange during the reaction.','Product particles move away.'],'Illustrative successful collision only; not every collision reacts. Abstract A/B symbols preserve the two particles, not a molecular reaction mechanism.',p=>{let q=Math.min(1,p*2),x=90+175*q,y=470-175*q;if(p>.5){x=265+(p-.5)*180;y=x+30;}return frame((p>.5?line([x,180],[y,180],'#d3dcd5',7):'')+ball(x,180,20)+dot(y,180,20,'#a6c5ca')+text(x,187,'A')+text(y,187,'B')+text(280,310,p<.5?'A + B':'AB',25),films.collision.steps[filmPhase(p,4)]);}),
 equilibrium:make('Dynamic equilibrium in a closed system',['Both forward and reverse reactions continue.','A forward event converts A into B.','A reverse event converts B into A.','At equilibrium the average forward and reverse rates are equal.'],'Markers represent reaction events, not particles travelling between vessels. Equal illustrative populations are not a general condition for equilibrium. Closed system; concentrations remain constant on average.',p=>{let a='<rect x="35" y="60" width="490" height="240" rx="24" fill="#ffffff08" stroke="#bed0ce"/>'+text(120,125,'A',32)+text(440,125,'B',32)+line([130,170],[430,170])+line([430,240],[130,240]);let u=(p*2)%1;return frame(a+dot(130+300*u,170,12)+dot(430-300*u,240,12,'#b1d0d3')+text(280,335,'Forward rate = reverse rate',20),'Two equal-rate reaction event tracers, moving in opposite directions.');}),
 ionic:make('Electron transfer: sodium and chlorine',['A sodium atom has one outer electron to transfer.','The electron transfers to the chlorine atom.','Na⁺ and Cl⁻ ions result.','Opposite charges attract; ionic bonding is electrostatic attraction.'],'Outer-electron schematic only; other electrons omitted. This is a pair illustration, not a complete ionic lattice or literal electron trajectory.',p=>{let s=filmPhase(p,4),a=`<circle cx="155" cy="175" r="62" fill="#adbdc2"/><circle cx="405" cy="175" r="74" fill="#b39c8f"/>`+text(155,182,s<2?'Na':'Na⁺',29)+text(405,182,s<2?'Cl':'Cl⁻',29);if(s<2)a+=dot(210+Math.max(0,p*4-1)*140,175,7);if(s>=2)a+=dot(350,175,7);if(s===3)a+=line([235,270],[330,270],'#edab94',5)+text(280,320,'Electrostatic attraction',20);return frame(a,films.ionic.steps[s]);}),
 electrolysis:make('Molten lead bromide: ion movement',['In molten PbBr₂, ions are free to move.','Pb²⁺ moves to the negative cathode; Br⁻ to the positive anode.','Lead ions gain electrons at the cathode, forming lead.','Bromide ions lose electrons at the anode, forming bromine.'],'Worked molten example, not aqueous product rules or apparatus instructions. Electrons transfer at electrodes; ions carry charge in the melt. Two bromide ions make each Br₂ molecule.',p=>{let s=filmPhase(p,4),u=Math.min(1,p*2),a='<path d="M40 90V290H520V90" fill="#b6d1d01a" stroke="#b8d0d1" stroke-width="3"/><rect x="75" y="80" width="25" height="175" fill="#b5c7ca"/><rect x="460" y="80" width="25" height="175" fill="#cfab95"/>'+text(95,45,'− Cathode')+text(465,45,'+ Anode');if(s<2)a+=dot(200-95*u,170,18,'#afc7ca')+text(200-95*u,176,'Pb²⁺',13)+[0,1].map(i=>dot(330+115*u,145+i*65,12)+text(330+115*u,150+i*65,'Br⁻',12)).join('');else a+=text(160,155,'Pb²⁺ gains electrons → lead',14)+text(370,240,'Br⁻ loses electrons → bromine',14)+ball(110,230,13)+(s===3?dot(430,130,12)+dot(452,130,12):'');return frame(a,films.electrolysis.steps[s]);}),
 chromatography:make('Chromatography: a spot separates',['A mixture starts on a pencil baseline above the solvent.','Solvent rises through the stationary phase.','Components travel at different rates.','Separated spots and the solvent front can be measured.'],'Two illustrative components; rates depend on stationary/mobile-phase interactions. Not a prediction for a named mixture. Replay resets the paper.',p=>{let front=280-p*210,a='<rect x="130" y="35" width="300" height="275" rx="5" fill="#e9e4d8"/><path d="M140 280H420" stroke="#566b75" stroke-width="2"/>'+line([140,front],[420,front],'#718f98',2)+dot(280,280-p*150,10,'#a1655b')+dot(280,280-p*75,10,'#5f8c92')+text(280,340,'Baseline → moving solvent front',18);return frame(a,'Solvent front rises and two components separate above the baseline.');}),
 distillation:make('Distillation: evaporate, cool, collect',['Heat causes the more volatile material to vaporise.','Vapour moves into the cooler condenser.','The vapour condenses into liquid.','Distillate is collected separately.'],'Simple distillation route, not a fractional-column simulation. Markers represent material flow; not a school apparatus construction guide.',p=>{let pts=[[100,270],[100,90],[350,180],[470,270]],a='<circle cx="100" cy="270" r="45" fill="#a4c5cc33" stroke="#c5d9d7" stroke-width="3"/>'+line(pts[0],pts[1])+line(pts[1],pts[2],'#b1c9cf',20)+line(pts[2],pts[3])+text(100,340,'Heated liquid',16)+text(330,105,'Cool condenser',16)+text(470,340,'Distillate',16);let v=p*3,i=Math.min(2,Math.floor(v)),u=v-i;return frame(a+dot(pts[i][0]+(pts[i+1][0]-pts[i][0])*u,pts[i][1]+(pts[i+1][1]-pts[i][1])*u,10),'Material vaporises, passes through condenser and collects as liquid.');})
};
