export function filmForLesson(l){return filmBindings[l.id]||filmBindings[l.widget]||null;}
export function processFrame(key,time){const f=films[key];if(!f)throw new Error('Unknown process film');const p=clampFilm(time),phase=filmPhase(p,f.steps.length);return{phase,caption:f.steps[phase],svg:f.render(p),progress:p};}
